<?php
declare(strict_types=1);
require_once __DIR__.'/config/communications_step21.php';
$error=null;$type=(string)($_GET['type']??'outbox');$format=(string)($_GET['format']??'view');$rows=[];$headers=[];$title='Communication Export';
try{$pdo=business_db();comm_step21_ensure($pdo);$ctx=comm_step21_context($pdo);$orgId=(int)$ctx['organization_id'];if($type==='events'){$title='Operational Communication Events';$headers=['Event Key','Event Type','Entity','Severity','Title','Status','Occurred','Resolved'];$s=$pdo->prepare("SELECT event_key,event_type,CONCAT(COALESCE(entity_type,''),CASE WHEN entity_id IS NULL THEN '' ELSE CONCAT(' #',entity_id) END) entity,severity,title,event_status,occurred_at,resolved_at FROM communication_events WHERE organization_id=? ORDER BY id DESC");$s->execute([$orgId]);$rows=$s->fetchAll(PDO::FETCH_NUM);}elseif($type==='notifications'){$title='In-App Notifications';$headers=['User','Title','Priority','Status','Created','Read'];$s=$pdo->prepare("SELECT u.full_name,n.title,n.priority,n.status,n.created_at,n.read_at FROM communication_notifications n JOIN system_users u ON u.id=n.user_id WHERE n.organization_id=? ORDER BY n.id DESC");$s->execute([$orgId]);$rows=$s->fetchAll(PDO::FETCH_NUM);}else{$type='outbox';$title='External Communication Outbox';$headers=['ID','Channel','Recipient Type','Recipient Name','Recipient Address','Subject','Status','Provider Mode','Scheduled','Attempts','Sent','Last Error'];$s=$pdo->prepare("SELECT id,channel,recipient_type,recipient_name_snapshot,recipient_address_snapshot,subject_snapshot,status,provider_mode,scheduled_at,attempts,sent_at,last_error FROM communication_outbox WHERE organization_id=? ORDER BY id DESC");$s->execute([$orgId]);$rows=$s->fetchAll(PDO::FETCH_NUM);}if($format==='csv'){header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="step21_'.preg_replace('/[^a-z0-9_-]+/i','_',$type).'_'.date('Ymd_His').'.csv"');echo "\xEF\xBB\xBF";$out=fopen('php://output','wb');fputcsv($out,$headers);foreach($rows as $r)fputcsv($out,$r);fclose($out);exit;}}catch(Throwable $e){$error=$e->getMessage();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title><?=comm_step21_h($title)?> - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"><style>@media print{.no-print{display:none!important}.os-topbar{display:none}.os-main{max-width:none!important}}</style></head><body><header class="os-topbar no-print"><div class="os-topbar-inner"><a class="os-brand" href="communication_center.php"><img src="../img/logo.png"><span><strong>Healthcare Wellness Club</strong><small>Communication Export Center</small></span></a><div class="os-top-actions"><a class="os-btn primary" href="communication_center.php">Communications</a></div></div></header><main class="os-main" style="max-width:1450px;margin:auto"><section class="os-hero pp-hero no-print"><div class="os-kicker">STEP 21 • EXPORT</div><h1>CSV and Print / Save PDF-ready communication evidence.</h1><p>Exports use the live communication ledger and do not invent provider delivery states.</p></section><?php if($error):?><div class="pp-alert bad"><?=comm_step21_h($error)?></div><?php endif;?><section class="os-card" style="margin-top:14px"><div class="os-title-row no-print"><div><h2><?=comm_step21_h($title)?></h2><p><?=count($rows)?> row(s)</p></div><div style="display:flex;gap:8px"><a class="os-btn" href="?type=<?=$type?>&format=csv">Download CSV</a><button class="os-btn" onclick="window.print()">Print / Save PDF</button></div></div><div class="pp-filterbar no-print"><a class="pp-chip <?=$type==='outbox'?'active':''?>" href="?type=outbox">Outbox</a><a class="pp-chip <?=$type==='events'?'active':''?>" href="?type=events">Events</a><a class="pp-chip <?=$type==='notifications'?'active':''?>" href="?type=notifications">In-App</a></div><h2><?=comm_step21_h($title)?></h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><?php foreach($headers as $h):?><th><?=comm_step21_h($h)?></th><?php endforeach;?></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="<?=count($headers)?>">No data.</td></tr><?php endif;?><?php foreach($rows as $r):?><tr><?php foreach($r as $v):?><td><?=comm_step21_h($v)?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div></section></main></body></html>